package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int64
	var x int
	fmt.Fscan(in, &n, &x)

	for move := n; move >= 1 && move > n-2; move-- {
		if move%2 == 1 {
			if x == 0 {
				x = 1
			} else if x == 1 {
				x = 0
			}
		} else {
			if x == 1 {
				x = 2
			} else if x == 2 {
				x = 1
			}
		}
	}

	remaining := n - 2
	if remaining > 0 {
		switch remaining % 3 {
		case 1:
			if x == 0 {
				x = 1
			} else if x == 1 {
				x = 0
			}
		case 2:
			if x == 0 {
				x = 2
			} else if x == 2 {
				x = 0
			}
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, x)
}

